import { useState, useEffect } from 'react';
import { getAdminDashboard } from '../api';
import { getUsers, updateUserStatus, updateUserRole } from '../api';
import { useAuth } from '../context/AuthContext';

const STATUS_COLORS = {
  approved:  { color: 'var(--green)', bg: 'var(--green-bg)', border: 'var(--green-border)' },
  pending:   { color: 'var(--amber)', bg: 'var(--amber-bg)', border: 'var(--amber-border)' },
  suspended: { color: '#7c3aed',      bg: '#f5f3ff',         border: '#ddd6fe' },
  banned:    { color: 'var(--red)',   bg: 'var(--red-bg)',   border: 'var(--red-border)' },
};

export default function AdminPage({ onBack }) {
  const { user: me } = useAuth();
  const [users, setUsers]     = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter]   = useState('all');
  const [search, setSearch]   = useState('');
  const [msg, setMsg]         = useState('');
  const [leadStats, setLeadStats] = useState([]);
  const [uploadCountry, setUploadCountry] = useState('US');
  const [uploading, setUploading] = useState(false);
  const [adminTab, setAdminTab] = useState('users');
  const fileRef = useRef();

  const load = async () => {
    try {
      const [userData, leadData] = await Promise.all([getUsers(), getAdminLeadStats()]);
      setUsers(userData);
      setLeadStats(leadData);
    } catch (e) {
      setMsg(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const handleLeadUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    try {
      const result = await uploadLeadsCSV(uploadCountry, file);
      setMsg(`✓ Uploaded ${result.inserted.toLocaleString()} new leads for ${uploadCountry} (${result.skipped_duplicates} duplicates skipped)`);
      const stats = await getAdminLeadStats();
      setLeadStats(stats);
    } catch (err) {
      setMsg(err.message);
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  const handleStatus = async (userId, status) => {
    try {
      await updateUserStatus(userId, status);
      setMsg(`User ${status} successfully`);
      load();
    } catch (e) { setMsg(e.message); }
  };

  const handleRole = async (userId, role) => {
    try {
      await updateUserRole(userId, role);
      setMsg(`Role updated to ${role}`);
      load();
    } catch (e) { setMsg(e.message); }
  };

  const filtered = users.filter(u => {
    if (filter !== 'all' && u.status !== filter) return false;
    if (search && !u.email.includes(search.toLowerCase()) && !u.name.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  const counts = {
    all: users.length,
    pending: users.filter(u => u.status === 'pending').length,
    approved: users.filter(u => u.status === 'approved').length,
    suspended: users.filter(u => u.status === 'suspended').length,
    banned: users.filter(u => u.status === 'banned').length,
  };

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg)' }}>
      {/* Nav */}
      <div style={{ borderBottom: '1px solid var(--border)', background: 'rgba(255,255,255,0.9)', backdropFilter: 'blur(12px)', position: 'sticky', top: 0, zIndex: 10 }}>
        <div style={{ maxWidth: 960, margin: '0 auto', padding: '0 16px', height: 56, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 28, height: 28, background: 'var(--accent)', borderRadius: 7, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 13 }}>✉</div>
            <span style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15 }}>MailClean</span>
            <span style={{ background: 'var(--red-bg)', color: 'var(--red)', border: '1px solid var(--red-border)', borderRadius: 5, padding: '1px 8px', fontSize: 10, fontFamily: 'DM Mono' }}>ADMIN</span>
          </div>
          <button className="btn-ghost" onClick={onBack} style={{ padding: '7px 16px', fontSize: 12 }}>← Back to dashboard</button>
        </div>
      </div>

      <div style={{ maxWidth: 960, margin: '0 auto', padding: '20px 16px 80px' }}>
        <div style={{ marginBottom: 28 }}>
          <h1 style={{ fontFamily: 'Syne', fontSize: 24, fontWeight: 700, letterSpacing: '-0.03em', marginBottom: 4 }}>Admin dashboard</h1>
          <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>Manage user access and monitor usage</p>
        </div>

        {/* Admin tabs */}
        <div style={{ display: 'flex', gap: 2, background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 10, padding: 3, width: 'fit-content', marginBottom: 20 }}>
          {[{ id: 'users', label: '👥 Users' }, { id: 'leads', label: '🎯 Lead pool' }].map(t => (
            <button key={t.id} onClick={() => setAdminTab(t.id)}
              style={{ background: adminTab === t.id ? 'var(--bg2)' : 'transparent', color: adminTab === t.id ? 'var(--text)' : 'var(--text-muted)', border: adminTab === t.id ? '1px solid var(--border-mid)' : '1px solid transparent', padding: '8px 20px', borderRadius: 8, fontFamily: 'Syne', fontWeight: 600, fontSize: 13, cursor: 'pointer' }}>
              {t.label}
            </button>
          ))}
        </div>

        {msg && (
          <div style={{ background: 'var(--green-bg)', border: '1px solid var(--green-border)', borderRadius: 'var(--radius)', padding: '10px 16px', color: 'var(--green)', fontSize: 13, marginBottom: 20 }}>
            {msg} <button onClick={() => setMsg('')} style={{ background: 'none', border: 'none', color: 'var(--green)', cursor: 'pointer', float: 'right', fontSize: 14 }}>×</button>
          </div>
        )}

        {adminTab === 'users' && (<>

        {/* Stat cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(100px, 1fr))', gap: 10, marginBottom: 24 }}>
          {Object.entries(counts).map(([key, count]) => (
            <div key={key} onClick={() => setFilter(key)}
              style={{ background: filter === key ? 'var(--accent)' : 'var(--bg2)', border: `1px solid ${filter === key ? 'var(--accent)' : 'var(--border)'}`, borderRadius: 'var(--radius-lg)', padding: '14px 16px', cursor: 'pointer', transition: 'all 0.15s', boxShadow: 'var(--shadow-sm)' }}>
              <div style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, color: filter === key ? '#fff' : 'var(--text)' }}>{count}</div>
              <div style={{ fontSize: 11, color: filter === key ? 'rgba(255,255,255,0.7)' : 'var(--text-muted)', textTransform: 'capitalize', marginTop: 2 }}>{key}</div>
            </div>
          ))}
        </div>

        {/* Search */}
        <div style={{ marginBottom: 16 }}>
          <input placeholder="Search by name or email..." value={search} onChange={e => setSearch(e.target.value)} style={{ maxWidth: 320 }} />
        </div>

        {/* Table */}
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-muted)' }}>Loading...</div>
        ) : (
          <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', overflow: 'hidden', boxShadow: 'var(--shadow-sm)', overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13, minWidth: 700 }}>
              <thead>
                <tr style={{ background: 'var(--bg3)', borderBottom: '1px solid var(--border-mid)' }}>
                  {['User', 'Role', 'Status', 'Emails verified', 'Last active', 'Actions'].map(h => (
                    <th key={h} style={{ padding: '11px 16px', textAlign: 'left', fontFamily: 'Syne', fontWeight: 600, fontSize: 11, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtered.map((u, i) => {
                  const sc = STATUS_COLORS[u.status] || STATUS_COLORS.pending;
                  const isMainAdmin = u.role === 'main_admin';
                  const isMe = u.email === me?.email;
                  return (
                    <tr key={u.id} style={{ borderBottom: i < filtered.length - 1 ? '1px solid var(--border)' : 'none' }}>
                      <td style={{ padding: '12px 16px' }}>
                        <div style={{ fontWeight: 500 }}>{u.name} {isMe && <span style={{ fontSize: 10, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>(you)</span>}</div>
                        <div style={{ fontSize: 11, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>{u.email}</div>
                      </td>
                      <td style={{ padding: '12px 16px' }}>
                        <span style={{ background: isMainAdmin ? 'var(--amber-bg)' : 'var(--bg3)', color: isMainAdmin ? 'var(--amber)' : 'var(--text-muted)', border: `1px solid ${isMainAdmin ? 'var(--amber-border)' : 'var(--border)'}`, borderRadius: 20, padding: '3px 10px', fontSize: 11, fontFamily: 'DM Mono' }}>
                          {u.role}
                        </span>
                      </td>
                      <td style={{ padding: '12px 16px' }}>
                        <span style={{ background: sc.bg, color: sc.color, border: `1px solid ${sc.border}`, borderRadius: 20, padding: '3px 10px', fontSize: 11, fontFamily: 'DM Mono' }}>{u.status}</span>
                      </td>
                      <td style={{ padding: '12px 16px', fontFamily: 'DM Mono', fontSize: 12 }}>
                        {(u.emails_verified || 0).toLocaleString()}
                      </td>
                      <td style={{ padding: '12px 16px', fontSize: 11, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
                        {u.last_active ? new Date(u.last_active).toLocaleDateString() : '—'}
                      </td>
                      <td style={{ padding: '12px 16px' }}>
                        {isMainAdmin ? (
                          <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>Protected</span>
                        ) : (
                          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                            {u.status !== 'approved' && (
                              <button onClick={() => handleStatus(u.id, 'approved')}
                                style={{ background: 'var(--green-bg)', color: 'var(--green)', border: '1px solid var(--green-border)', padding: '4px 10px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                                Approve
                              </button>
                            )}
                            {u.status !== 'suspended' && (
                              <button onClick={() => handleStatus(u.id, 'suspended')}
                                style={{ background: '#f5f3ff', color: '#7c3aed', border: '1px solid #ddd6fe', padding: '4px 10px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                                Suspend
                              </button>
                            )}
                            {u.status !== 'banned' && (
                              <button onClick={() => handleStatus(u.id, 'banned')}
                                style={{ background: 'var(--red-bg)', color: 'var(--red)', border: '1px solid var(--red-border)', padding: '4px 10px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                                Ban
                              </button>
                            )}
                            {me?.role === 'main_admin' && u.role !== 'admin' && (
                              <button onClick={() => handleRole(u.id, 'admin')}
                                style={{ background: 'var(--amber-bg)', color: 'var(--amber)', border: '1px solid var(--amber-border)', padding: '4px 10px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                                Make admin
                              </button>
                            )}
                            {me?.role === 'main_admin' && u.role === 'admin' && (
                              <button onClick={() => handleRole(u.id, 'user')}
                                style={{ background: 'var(--bg3)', color: 'var(--text-muted)', border: '1px solid var(--border)', padding: '4px 10px', borderRadius: 7, fontSize: 11, fontFamily: 'Syne', fontWeight: 600, cursor: 'pointer' }}>
                                Remove admin
                              </button>
                            )}
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
                {filtered.length === 0 && (
                  <tr><td colSpan={6} style={{ padding: '40px', textAlign: 'center', color: 'var(--text-dim)', fontSize: 13 }}>No users found</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}
        </>)}

        {adminTab === 'leads' && (
          <div className="animate-in">
            {/* Lead pool stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 12, marginBottom: 24 }}>
              {leadStats.map(s => (
                <div key={s.country} style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '18px 20px', boxShadow: 'var(--shadow-sm)' }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
                    <span style={{ fontSize: 24 }}>{s.flag}</span>
                    <span style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15 }}>{s.name}</span>
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {[
                      { label: 'Total uploaded', value: s.total, color: 'var(--text)' },
                      { label: 'Available', value: s.available, color: 'var(--green)' },
                      { label: 'Claimed', value: s.claimed, color: 'var(--amber)' },
                    ].map(row => (
                      <div key={row.label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>{row.label}</span>
                        <span style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 16, color: row.color }}>{row.value.toLocaleString()}</span>
                      </div>
                    ))}
                    {/* Progress bar */}
                    <div style={{ height: 5, background: 'var(--bg3)', borderRadius: 99, overflow: 'hidden', marginTop: 4 }}>
                      <div style={{ height: '100%', width: s.total > 0 ? `${Math.round((s.claimed / s.total) * 100)}%` : '0%', background: 'var(--amber)', borderRadius: 99 }} />
                    </div>
                    <div style={{ fontSize: 10, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
                      {s.total > 0 ? Math.round((s.claimed / s.total) * 100) : 0}% claimed
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* Upload new CSV */}
            <div style={{ background: 'var(--bg2)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '22px 24px', boxShadow: 'var(--shadow-sm)' }}>
              <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 15, marginBottom: 4 }}>Upload new leads</div>
              <div style={{ fontSize: 13, color: 'var(--text-muted)', marginBottom: 20 }}>
                Upload a CSV file — the system auto-detects the email column and skips duplicate emails.
              </div>
              <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
                <div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 6, fontFamily: 'Syne', fontWeight: 500 }}>Country</div>
                  <select value={uploadCountry} onChange={e => setUploadCountry(e.target.value)}
                    style={{ padding: '9px 14px', fontSize: 13, borderRadius: 9, minWidth: 160 }}>
                    <option value="US">🇺🇸 United States</option>
                    <option value="GB">🇬🇧 United Kingdom</option>
                    <option value="CA">🇨🇦 Canada</option>
                    <option value="AU">🇦🇺 Australia</option>
                  </select>
                </div>
                <div style={{ paddingTop: 22 }}>
                  <input ref={fileRef} type="file" accept=".csv" style={{ display: 'none' }} onChange={handleLeadUpload} />
                  <button
                    onClick={() => fileRef.current.click()}
                    disabled={uploading}
                    className="btn-primary"
                    style={{ padding: '10px 22px', fontSize: 13 }}>
                    {uploading ? <><span className="spinner" style={{ marginRight: 8 }}>↻</span>Uploading...</> : '⬆ Upload CSV'}
                  </button>
                </div>
              </div>
              <div style={{ marginTop: 14, fontSize: 12, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
                Duplicates are skipped automatically · Email column is auto-detected · Multiple emails per row are split
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
